import sys
from collections import deque

data = sys.stdin.buffer.read().split()
n = int(data[0]); m = int(data[1]); k = int(data[2])
adj = [[] for _ in range(n + 1)]
p = 3
for _ in range(m):
    x = int(data[p]); y = int(data[p + 1]); t = int(data[p + 2]); p += 3
    adj[x].append((y, t))
    adj[y].append((x, t))
color = [-1] * (n + 1)
groups = []
bad = False
for s in range(1, n + 1):
    if color[s] != -1:
        continue
    color[s] = 0
    members = [s]
    q = deque([s])
    while q:
        u = q.popleft()
        for v, t in adj[u]:
            want = color[u] ^ t
            if color[v] == -1:
                color[v] = want
                members.append(v)
                q.append(v)
            elif color[v] != want:
                bad = True
    groups.append(members)
if bad:
    print(-1)
    sys.exit()
sizes = []
for mem in groups:
    a = sum(1 for v in mem if color[v] == 0)
    sizes.append((a, len(mem) - a))
full = 1
for a, b in sizes:
    full = (full << a) | (full << b)
if k > n or not (full >> k) & 1:
    print(-1)
    sys.exit()
ans = [""] * (n + 1)
cache = {}
for j, mem in enumerate(groups):
    a, b = sizes[j]
    bits = cache.get((a, b))
    if bits is None:
        # Groups with the same pair of side sizes leave the same multiset behind.
        bits = 1
        for i2, (c, e) in enumerate(sizes):
            if i2 == j:
                continue
            bits = (bits << c) | (bits << e)
        cache[(a, b)] = bits
    ok_a = k >= a and (bits >> (k - a)) & 1
    ok_b = k >= b and (bits >> (k - b)) & 1
    for v in mem:
        if ok_a and ok_b:
            ans[v] = "?"
        elif ok_a:
            ans[v] = "C" if color[v] == 0 else "T"
        else:
            ans[v] = "T" if color[v] == 0 else "C"
print("".join(ans[1:]))
